//! Tenant/revision-bound read-only contributor bridge. Discovery is metadata-only.
use serde::{Deserialize,Serialize};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,BTreeSet},future::Future,pin::Pin,sync::Arc};
#[derive(Debug,Clone,PartialEq,Eq)]pub struct ReadonlyCapabilityError(pub &'static str);
impl std::fmt::Display for ReadonlyCapabilityError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.write_str(self.0)}}
impl std::error::Error for ReadonlyCapabilityError{}
pub type Result<T>=std::result::Result<T,ReadonlyCapabilityError>;
pub type Contribution<'a,T>=Pin<Box<dyn Future<Output=Result<T>>+Send+'a>>;
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct RuntimeCapabilityScope{pub tenant_id:String,pub user_id:String,pub session_id:String,pub capability_revision:i64,#[serde(default)]pub snapshot_id:String}
impl RuntimeCapabilityScope{pub fn validate(&self)->Result<()>{if [&self.tenant_id,&self.user_id,&self.session_id].iter().any(|s|s.is_empty()){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_SCOPE_INVALID"))}if self.capability_revision<1{return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_REVISION_INVALID"))}Ok(())}}
#[derive(Debug,Clone,Default,Serialize,Deserialize)]pub struct TurnInput{pub turn_id:String,#[serde(default)]pub attachment_ids:Vec<String>,#[serde(default)]pub knowledge_refs:Vec<String>,#[serde(default)]pub memory_refs:Vec<String>,#[serde(default="empty_object")]pub page_context:Value}
fn empty_object()->Value{json!({})}fn yes()->bool{true}fn nonauthoritative()->String{"non_authoritative".into()}fn tool()->String{"tool".into()}fn internal()->String{"internal".into()}fn general()->String{"general".into()}
fn name(s:&str)->bool{!s.is_empty()&&s.len()<=160&&s.bytes().all(|b|b.is_ascii_alphanumeric()||b"_.:/-".contains(&b))}
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct CapabilityItem{pub item_id:String,pub kind:String,pub tenant_id:String,pub capability_revision:i64,pub source:String,pub payload:Value,#[serde(default="yes")]pub untrusted:bool,#[serde(default="nonauthoritative")]pub authority:String}
impl CapabilityItem{pub fn validate(&self)->Result<()>{if !name(&self.item_id)||!name(&self.source){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_ITEM_ID_INVALID"))}if !["context","turn_input","knowledge","attachment","citation","artifact","office_read"].contains(&self.kind.as_str()){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_ITEM_KIND_INVALID"))}if !self.payload.is_object(){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_ITEM_PAYLOAD_INVALID"))}if self.authority!="non_authoritative"{return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_AUTHORITY_INVALID"))}Ok(())}}
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct CapabilityDescriptor{pub name:String,pub description:String,pub schema:Value,pub tenant_id:String,pub capability_revision:i64,pub source:String,#[serde(default="tool")]pub kind:String,#[serde(default="yes")]pub read_only:bool,#[serde(default)]pub tags:Vec<String>,#[serde(default="internal")]pub protocol:String,#[serde(default="general")]pub category:String,#[serde(default="empty_object")]pub metadata:Value}
impl CapabilityDescriptor{pub fn validate(&self)->Result<()>{if !name(&self.name)||!name(&self.source){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_DESCRIPTOR_ID_INVALID"))}if self.description.is_empty(){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_DESCRIPTOR_DESCRIPTION_INVALID"))}if !self.schema.is_object(){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_DESCRIPTOR_SCHEMA_INVALID"))}if !self.read_only{return Err(ReadonlyCapabilityError("RUNTIME_READONLY_CAPABILITY_REQUIRED"))}if self.tags.iter().any(String::is_empty){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_TAG_INVALID"))}Ok(())}}
pub trait ContextContributor:Send+Sync{fn contribute<'a>(&'a self,scope:&'a RuntimeCapabilityScope)->Contribution<'a,Vec<CapabilityItem>>;}
pub trait TurnInputContributor:Send+Sync{fn contribute<'a>(&'a self,scope:&'a RuntimeCapabilityScope,turn:&'a TurnInput)->Contribution<'a,Vec<CapabilityItem>>;}
pub trait ToolContributor:Send+Sync{fn describe<'a>(&'a self,scope:&'a RuntimeCapabilityScope)->Contribution<'a,Vec<CapabilityDescriptor>>;}
pub trait McpServerContributor:Send+Sync{fn discover<'a>(&'a self,scope:&'a RuntimeCapabilityScope)->Contribution<'a,Vec<CapabilityDescriptor>>;}
pub trait TurnItemContributor:Send+Sync{fn project<'a>(&'a self,scope:&'a RuntimeCapabilityScope,item:CapabilityItem)->Contribution<'a,Option<CapabilityItem>>;}
#[derive(Default)]pub struct Contributors{pub context:Vec<Arc<dyn ContextContributor>>,pub turn_input:Vec<Arc<dyn TurnInputContributor>>,pub tools:Vec<Arc<dyn ToolContributor>>,pub mcp:Vec<Arc<dyn McpServerContributor>>,pub items:Vec<Arc<dyn TurnItemContributor>>}
pub struct ReadonlyCapabilityBridge{scope:RuntimeCapabilityScope,contributors:Contributors}
impl ReadonlyCapabilityBridge{
 pub fn new(scope:RuntimeCapabilityScope,contributors:Contributors)->Result<Self>{scope.validate()?;Ok(Self{scope,contributors})}
 pub fn scope(&self)->&RuntimeCapabilityScope{&self.scope}
 fn check_scope(&self,scope:Option<&RuntimeCapabilityScope>)->Result<()>{if scope.is_some_and(|s|s!=&self.scope){Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_SCOPE_MISMATCH"))}else{Ok(())}}
 fn check_item(&self,item:&CapabilityItem)->Result<CapabilityItem>{if item.tenant_id!=self.scope.tenant_id||item.capability_revision!=self.scope.capability_revision{return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_REVISION_MISMATCH"))}item.validate()?;Ok(item.clone())}
 fn check_descriptor(&self,item:&CapabilityDescriptor)->Result<CapabilityDescriptor>{if item.tenant_id!=self.scope.tenant_id||item.capability_revision!=self.scope.capability_revision{return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_REVISION_MISMATCH"))}item.validate()?;if !item.metadata.is_object(){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_PAYLOAD_INVALID"))}let mut out=item.clone();out.tags=out.tags.into_iter().collect::<BTreeSet<_>>().into_iter().collect();Ok(out)}
 pub async fn collect_context(&self,scope:Option<&RuntimeCapabilityScope>)->Result<Vec<CapabilityItem>>{self.check_scope(scope)?;let mut out=vec![];for c in &self.contributors.context{for item in c.contribute(&self.scope).await?{out.push(self.check_item(&item)?);}}Ok(stable(out))}
 pub async fn collect_turn_input(&self,turn:&TurnInput,scope:Option<&RuntimeCapabilityScope>)->Result<Vec<CapabilityItem>>{self.check_scope(scope)?;if turn.turn_id.is_empty(){return Err(ReadonlyCapabilityError("RUNTIME_TURN_INPUT_INVALID"))}let mut out=vec![];for c in &self.contributors.turn_input{for item in c.contribute(&self.scope,turn).await?{out.push(self.check_item(&item)?);}}Ok(stable(out))}
 pub async fn discover_tools(&self,metadata:Option<&Value>,scope:Option<&RuntimeCapabilityScope>)->Result<Vec<CapabilityDescriptor>>{self.check_scope(scope)?;let empty=empty_object();let filters=metadata.filter(|v|!v.is_null()).unwrap_or(&empty).as_object().ok_or(ReadonlyCapabilityError("RUNTIME_DISCOVERY_FILTER_INVALID"))?;if ["query","prompt","keywords","text"].iter().any(|k|filters.contains_key(*k)){return Err(ReadonlyCapabilityError("RUNTIME_METADATA_ONLY_DISCOVERY"))}if filters.keys().any(|k|!["kind","source","tags","protocol","category"].contains(&k.as_str())){return Err(ReadonlyCapabilityError("RUNTIME_DISCOVERY_FILTER_INVALID"))}let mut all=vec![];for c in &self.contributors.tools{for d in c.describe(&self.scope).await?{all.push(self.check_descriptor(&d)?);}}for c in &self.contributors.mcp{for d in c.discover(&self.scope).await?{all.push(self.check_descriptor(&d)?);}}let mut unique=BTreeMap::new();for d in all{let key=(d.source.clone(),d.name.clone());if unique.contains_key(&key){return Err(ReadonlyCapabilityError("RUNTIME_CAPABILITY_NAME_COLLISION"))}if matches_metadata(&d,filters){unique.insert(key,d);}}let mut out:Vec<_>=unique.into_values().collect();out.sort_by_key(|d|(d.source.to_ascii_lowercase(),d.name.to_ascii_lowercase()));Ok(out)}
 pub async fn project_item(&self,item:&CapabilityItem,scope:Option<&RuntimeCapabilityScope>)->Result<CapabilityItem>{self.check_scope(scope)?;let mut current=self.check_item(item)?;for c in &self.contributors.items{if let Some(next)=c.project(&self.scope,current.clone()).await?{current=self.check_item(&next)?;}}Ok(current)}
 pub async fn project_items(&self,items:&[CapabilityItem],scope:Option<&RuntimeCapabilityScope>)->Result<Vec<CapabilityItem>>{self.check_scope(scope)?;let mut out=vec![];for item in items{out.push(self.project_item(item,scope).await?)}Ok(stable(out))}
 pub fn project(&self,id:&str,kind:&str,source:&str,payload:&Value,untrusted:bool)->Result<CapabilityItem>{self.check_item(&CapabilityItem{item_id:id.into(),kind:kind.into(),source:source.into(),payload:payload.clone(),tenant_id:self.scope.tenant_id.clone(),capability_revision:self.scope.capability_revision,untrusted,authority:nonauthoritative()})}
 fn specific(&self,id:&str,kind:&str,source:&str,mut payload:Value,metadata:&Value)->Result<CapabilityItem>{let extra=metadata.as_object().ok_or(ReadonlyCapabilityError("RUNTIME_CAPABILITY_PAYLOAD_INVALID"))?;payload.as_object_mut().unwrap().extend(extra.clone());self.project(id,kind,source,&payload,true)}
 pub fn knowledge(&self,id:&str,content:&str,metadata:&Value)->Result<CapabilityItem>{self.specific(&format!("knowledge:{id}"),"knowledge",id,json!({"source_id":id,"content":content}),metadata)}
 pub fn attachment(&self,id:&str,reference:&str,metadata:&Value)->Result<CapabilityItem>{self.specific(&format!("attachment:{id}"),"attachment",id,json!({"attachment_id":id,"content_ref":reference}),metadata)}
 pub fn citation(&self,id:&str,source:&str,locator:&str,metadata:&Value)->Result<CapabilityItem>{self.specific(&format!("citation:{id}"),"citation",source,json!({"citation_id":id,"source_id":source,"locator":locator}),metadata)}
 pub fn artifact(&self,id:&str,reference:&str,media:&str,metadata:&Value)->Result<CapabilityItem>{self.specific(&format!("artifact:{id}"),"artifact",id,json!({"artifact_id":id,"content_ref":reference,"media_type":media}),metadata)}
 pub fn office_read(&self,id:&str,format:&str,extracted:Value,metadata:&Value)->Result<CapabilityItem>{self.specific(&format!("office-read:{id}"),"office_read",id,json!({"artifact_id":id,"format":format,"extracted":extracted}),metadata)}
}
fn stable(items:Vec<CapabilityItem>)->Vec<CapabilityItem>{let mut unique=BTreeMap::new();for item in items{unique.entry((item.kind.clone(),item.item_id.clone())).or_insert(item);}unique.into_values().collect()}
fn python_str(v:&Value)->String{match v{Value::String(s)=>s.clone(),Value::Bool(true)=>"True".into(),Value::Bool(false)=>"False".into(),Value::Null=>"None".into(),_=>v.to_string()}}
fn matches_metadata(d:&CapabilityDescriptor,filters:&serde_json::Map<String,Value>)->bool{for(k,v)in filters{if k=="tags"{let wanted:Vec<_>=v.as_array().map(|a|a.iter().map(python_str).collect()).unwrap_or_else(||vec![python_str(v)]);if wanted.iter().any(|w|!d.tags.contains(w)){return false}}else{let actual=match k.as_str(){"kind"=>&d.kind,"source"=>&d.source,"protocol"=>&d.protocol,"category"=>&d.category,_=>return false};if v.as_str()!=Some(actual.as_str()){return false}}}true}
